query:
-- Add indexes for multi-tenant performance
-- Tasks: org_id + status + due_date for filtered queries
CREATE INDEX IF NOT EXISTS idx_tasks_org_status ON tasks (organizationId, status);
CREATE INDEX IF NOT EXISTS idx_tasks_org_due ON tasks (organizationId, dueDate);
CREATE INDEX IF NOT EXISTS idx_tasks_venture ON tasks (ventureId);

-- Agent events: org_id + created_at for timeline queries
CREATE INDEX IF NOT EXISTS idx_agent_events_org ON agent_events (organizationId, createdAt);
CREATE INDEX IF NOT EXISTS idx_agent_events_agent ON agent_events (agentName, createdAt);

-- Activity log: org_id + created_at for timeline queries
CREATE INDEX IF NOT EXISTS idx_activity_org ON activity_log (organizationId, createdAt);
CREATE INDEX IF NOT EXISTS idx_activity_entity ON activity_log (entityType, createdAt);

-- SPVs: org_id + stage for filtered queries
CREATE INDEX IF NOT EXISTS idx_spvs_org ON spvs (organizationId, stage);

-- Distributions: org_id + status for filtered queries
CREATE INDEX IF NOT EXISTS idx_distributions_org ON distributions (organizationId, status);

-- Org venture access: org_id for join queries
CREATE INDEX IF NOT EXISTS idx_org_venture_org ON org_venture_access (organizationId);
CREATE INDEX IF NOT EXISTS idx_org_venture_venture ON org_venture_access (ventureId);

-- Invitations: org_id + status for filtered queries
CREATE INDEX IF NOT EXISTS idx_invitations_org ON invitations (organizationId, inviteStatus);
CREATE INDEX IF NOT EXISTS idx_invitations_token ON invitations (token);

-- Daily briefs, smart alerts, AI observations: org_id
CREATE INDEX IF NOT EXISTS idx_daily_briefs_org ON daily_briefs (organizationId, createdAt);
CREATE INDEX IF NOT EXISTS idx_smart_alerts_org ON smart_alerts (organizationId, createdAt);
CREATE INDEX IF NOT EXISTS idx_ai_observations_org ON ai_observations (organizationId, createdAt);

-- Venture velocity: org_id + venture
CREATE INDEX IF NOT EXISTS idx_venture_velocity_org ON venture_velocity (organizationId, ventureId);

-- Contacts: org_id
CREATE INDEX IF NOT EXISTS idx_contacts_org ON contacts (organizationId);

-- Audit log: org_id + timestamp
CREATE INDEX IF NOT EXISTS idx_audit_log_org ON audit_log (organizationId, timestamp);

